package vn.edu.hcmute.bookstore_24110202.controller; import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; import vn.edu.hcmute.bookstore_24110202.service.impl.*; import vn.edu.hcmute.bookstore_24110202.util.*;
@WebServlet("/book/detail") public class BookDetailController_24110202 extends HttpServlet {private final BookServiceImpl_24110202 books=new BookServiceImpl_24110202();private final RatingServiceImpl_24110202 ratings=new RatingServiceImpl_24110202();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Integer id=ValidationUtil_24110202.integer(q.getParameter("id"));if(id==null||id<1){p.sendError(404);return;}var b=books.find(id);if(b.isEmpty()){p.sendError(404);return;}q.setAttribute("book",b.get());q.setAttribute("reviews",ratings.reviews(id));q.setAttribute("reviewCount",ratings.count(id));q.getRequestDispatcher("/WEB-INF/views/book/detail.jsp").include(q,p);} }
